mapper.select:
SELECT id, email, module, (status + 0) AS status, cancel_reason, DATE_FORMAT(create_time, '%Y-%m-%d %H:%i:%s') AS create_time, DATE_FORMAT(update_time, '%Y-%m-%d %H:%i:%s') AS update_time FROM portal.t_subscription
AND email LIKE CONCAT('%', #{email}, '%')
AND module = #{module}
AND status = #{status}
ORDER BY id DESC

mapper.update:
UPDATE portal.t_subscription
SET status = 1, cancel_reason = NULL, update_time = NOW()
WHERE email = #{email} AND module = #{module}

mapper.delete:
DELETE FROM portal.t_subscription
WHERE id IN

    #{id}
